<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue'
import {Rabbit,Search,SlidersHorizontal,Plus,ArrowUpRight,ArrowRight,ChevronDown,Sun,Moon,ShieldCheck,Users,Flower2,Clock3,MapPin,RefreshCw,Check,Copy,Link2,UserRound,LogOut,Inbox,Bookmark,LoaderCircle,LayoutGrid,Flag,Mail,Trash2,ExternalLink,Bell,Volume2,VolumeX} from 'lucide-vue-next'
import {api,auth,features,loadSession,saved,saveManaged,manageLink,labels,flowers,number,date,token} from './api'
import {priceValue,priceUnit} from './card-pricing'
import Sheet from './components/Sheet.vue'
import TeamCard from './components/TeamCard.vue'
import CardForm from './components/CardForm.vue'
import ApplyForm from './components/ApplyForm.vue'
import AuthForm from './components/AuthForm.vue'
import ApplicationPanel from './components/ApplicationPanel.vue'
import HumanCheck from './components/HumanCheck.vue'
import AdminPanel from './components/AdminPanel.vue'
import PartnerBoard from './components/PartnerBoard.vue'
import mapCatalog from './data/popular-maps.json'
import {mapOptions} from './map-options'
import {useNotifications} from './useNotifications'
import {badgeNumber} from './notification-state'
import ApplicationNotice from './components/ApplicationNotice.vue'
import ProfilePanel from './components/ProfilePanel.vue'
import CaptainDashboard from './components/CaptainDashboard.vue'
import BossBookings from './components/BossBookings.vue'

const partnerBoard=ref(null),personalPartnerBoard=ref(null)
const {total:pendingCount,counts:pendingCounts,banner:applicationBanner,updates:unreadUpdates,items:notificationItems,available:notificationsAvailable,markRead:markNotificationsRead,soundEnabled,soundReady,toggleSound,refresh:refreshNotifications,dismiss:dismissNotification}=useNotifications()
const cardSort=ref('availability')
const tab=ref('team'),sheet=ref(''),loading=ref(true),error=ref(''),busy=ref(false),notice=ref(''),query=ref(''),cards=ref([]),page=ref(1),total=ref(0),hasMore=ref(false)
const allNavigation=[
  {key:'team',label:'挂绳队伍',hint:'查看打手队伍，申请上车',icon:Users,count:'teams',publish:'发布队伍',description:'查看打手队伍，申请上车。'},
  {key:'boss',label:'老板发布',hint:'打手认领，选择心仪老板入队',icon:Search,count:'bosses',publish:'发布求带',description:'打手认领，选择心仪老板入队。'},
  {key:'partner',label:'队友招募',hint:'打手、祭司互找队友',icon:Flower2,count:'partners',publish:'发布队友招募',description:'打手、祭司互找队友，也可以发布祭司求职。'},
  {key:'mine',label:'我的记录',hint:'发布、申请和上车',icon:UserRound,publish:'发布队伍',description:'管理你的发布、申请和上车进度。'},
]
const navigation=computed(()=>allNavigation.filter(section=>features.teammate_recruitment||section.key!=='partner'))
const currentSection=computed(()=>navigation.value.find(section=>section.key===tab.value))
const meta=ref({teams:0,bosses:0,partners:0,maps:[],email_recovery:false}),detail=ref(null),application=ref(null),selected=ref(null),manage=ref(''),publishKind=ref('team'),editing=ref(null),success=ref(null),policy=ref('safety')
const resumeIntent=ref(null),claimAfterPublish=ref(null),captainDashboard=ref(null)
const captainTeams=ref([]),bossBookings=ref([]),bossBookingsError=ref(''),waitingBossCards=ref([]),mineError=ref('')
const mine=ref({cards:[],incoming:[],outgoing:[],characters:[]}),myTab=ref('cards'),localItems=ref(saved()),human=ref(null)
const filters=ref({map_name:'',level:'',flower:'',capacity:'',price_mode:'',exp_min:'',exp_max:'',at_time:'',available:false})
const draftFilters=ref({...filters.value}),report=ref({resource:'team',resource_id:1,reason:'',challenge_id:'',answer:'',website:''})
const recovery=ref({resource:'boss',resource_id:1,email:'',code:''}),recoveryMode=ref('recover'),recoveryStage=ref(0)
const theme=ref(localStorage.getItem('rabbit-theme')||'light');watch(theme,v=>{document.documentElement.dataset.theme=v;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',v==='dark'?'#121514':'#f5f6f7');localStorage.setItem('rabbit-theme',v)},{immediate:true})
const filterApplies=k=>(features.teammate_recruitment||k!=='flower')&&(tab.value!=='boss'||!['capacity','flower','available'].includes(k))
const activeFilters=computed(()=>Object.entries(filters.value).filter(([k,v])=>filterApplies(k)&&v!==''&&v!==false).length)
const title=computed(()=>({auth:'欢迎回到小白兔',publish:editing.value?'编辑卡片':publishKind.value==='team'?'发布队伍':'发布求带',apply:selected.value?.type==='team'?'申请上车':'认领老板',filters:tab.value==='boss'?'筛选老板需求':'筛选挂绳队伍',detail:detail.value?.map_name||'卡片详情',application:'上车安排与联系',success:'提交成功',policy:policy.value==='safety'?'防骗须知':'隐私政策',report:report.value.resource==='appeal'?'提交申诉':'举报内容',admin:'管理后台',recovery:recoveryMode.value==='bind'?'绑定恢复邮箱':'找回管理链接'}[sheet.value]||''))
let timer,searchTimer,noticeTimer,serial=0
function toast(s){notice.value=s;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',4000)}
async function fetchMeta(){try{const data=await api('/meta');Object.assign(features,data.features||{});meta.value={...data,maps:mapOptions(mapCatalog,data.maps)}}catch{}}
async function load(more=false,silent=false){if(['mine','partner'].includes(tab.value))return;const id=++serial;if(!silent)loading.value=true;error.value='';try{const qs=new URLSearchParams({q:query.value,page:more?page.value+1:1,sort:tab.value==='team'?cardSort.value:'latest'});for(const [k,v]of Object.entries(filters.value))if(filterApplies(k)&&v!==''&&v!==false)qs.set(k,v);const r=await api('/'+tab.value+'-cards?'+qs);if(id!==serial)return;cards.value=more?[...cards.value,...r.items]:r.items;page.value=r.page;total.value=r.total;hasMore.value=r.has_more}catch(e){if(id===serial)error.value=e.message}finally{if(id===serial)loading.value=false}}
async function loadBossBookings(){bossBookingsError.value='';const managed=saved().filter(r=>['boss','application'].includes(r.type)).slice(0,100).map(({type,id,manage})=>({type,id,manage}));if(!auth.user&&!managed.length){bossBookings.value=[];return}try{bossBookings.value=(await api('/boss/bookings/query',{method:'POST',data:{managed},notify:false})).bookings}catch(e){bossBookingsError.value=e.message}}
function openBossBooking(booking){const credential=saved().find(r=>r.type===booking.access.type&&r.id===booking.access.id)?.manage||'';openApplication(booking.application_id,credential)}
async function loadMine(){localItems.value=saved();mineError.value='';const bookingRequest=loadBossBookings();if(!auth.user){captainTeams.value=[];mine.value={cards:[],incoming:[],outgoing:[],characters:[]};await bookingRequest;const rows=localItems.value.filter(r=>r.type==='boss').slice(0,10);const results=await Promise.allSettled(rows.map(r=>api('/boss-cards/'+r.id,{manage:r.manage})));waitingBossCards.value=results.flatMap((result,i)=>result.status==='fulfilled'&&result.value.status==='active'?[{...result.value,credential:rows[i].manage}]:[]);if(results.some(r=>r.status==='rejected'))mineError.value='部分求带记录暂时无法加载，请重试。原管理入口仍保留在下方。';return}waitingBossCards.value=[];try{const [records,roster]=await Promise.all([api('/me'),api('/captain/teams'),bookingRequest]);mine.value=records;captainTeams.value=roster.teams}catch(e){mineError.value=e.message}}

watch(tab,()=>{if(tab.value==='mine')loadMine();else load()})
watch(()=>unreadUpdates.value.map(item=>item.id).join(','),async()=>{if(tab.value==='mine'&&!sheet.value)loadMine();if(sheet.value!=='application'||!application.value)return;const id=application.value.id,credential=manage.value;try{const row=await api('/applications/'+id,{manage:credential});if(sheet.value==='application'&&application.value?.id===id)application.value=row}catch{}})
watch(cardSort,()=>load())
watch(query,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>load(),300)})
function close(){if(sheet.value==='auth')resumeIntent.value=null;if(sheet.value==='publish')claimAfterPublish.value=null;sheet.value='';error.value='';history.replaceState(null,'',location.pathname+location.search)}
function filterOpen(){draftFilters.value={...filters.value};sheet.value='filters'}
function filterApply(){filters.value={...draftFilters.value};close();load()}
function clearFilters(){filters.value={map_name:'',level:'',flower:'',capacity:'',price_mode:'',exp_min:'',exp_max:'',at_time:'',available:false};query.value='';load()}
async function publish(kind=tab.value==='partner'?'partner':tab.value==='boss'?'boss':'team'){if(kind==='partner'){partnerBoard.value?.publish();return}publishKind.value=kind;editing.value=null;manage.value='';if(kind==='team'&&!auth.user){resumeIntent.value={kind:'publish',value:kind};sheet.value='auth';toast('发布队伍需要登录；发布求带无需注册');return}await loadMine();sheet.value='publish'}
async function openDetail(card,credential=''){busy.value=true;try{manage.value=credential||saved().find(x=>x.type===card.type&&x.id===card.id)?.manage||'';detail.value=await api('/'+card.type+'-cards/'+card.id,{manage:manage.value});sheet.value='detail'}catch(e){toast(e.message)}finally{busy.value=false}}
function apply(card){if(card.status!=='active'){toast('这张卡片已满员、下架或被认领，请选择其他卡片');close();load();return}if(card.type==='boss'&&!auth.user){resumeIntent.value={kind:'apply',value:card};sheet.value='auth';toast('认领老板需要登录并发布队伍');return}selected.value=card;sheet.value='apply'}
async function onSaved(result){success.value=result;sheet.value='success';await Promise.all([fetchMeta(),load(),loadMine()]);if(result.type==='team'&&claimAfterPublish.value){const target=claimAfterPublish.value;claimAfterPublish.value=null;try{const fresh=await api('/boss-cards/'+target.id);if(fresh.status==='active'){apply(fresh);toast('队伍已发布，继续认领这位老板');return}}catch{}toast('队伍已发布；原老板需求已变化，可查看其他老板')}if(result.claimed){await openApplication(result.id);toast('认领成功，已获得老板微信，老板已收到通知')}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制')}catch{toast('复制不可用，请长按选中文字复制')}}
async function logout(){await api('/auth/logout',{method:'POST'});auth.user=null;auth.csrf=null;loadMine();toast('已退出登录')}
async function onAuth(){const intent=resumeIntent.value;close();await loadMine();toast('登录成功');if(intent?.kind==='publish')await publish(intent.value);else if(intent?.kind==='apply'){try{apply(await api('/boss-cards/'+intent.value.id))}catch(e){toast(e.message)}}}
async function prepareClaimTeam(){claimAfterPublish.value=selected.value;await publish('team')}
async function returnToCards(){const kind=selected.value?.type||'team';close();tab.value=kind;await load()}
async function manageBooking(id){close();tab.value='mine';myTab.value='cards';await loadMine();await nextTick();captainDashboard.value?.editSchedule(id);document.getElementById('boss-booking-'+id)?.scrollIntoView({behavior:'smooth',block:'center'})}
async function openApplication(id,credential=''){try{manage.value=credential;application.value=await api('/applications/'+id,{manage:credential});sheet.value='application';await markNotificationsRead(unreadUpdates.value.filter(item=>item.application_id===id&&item.side===application.value.side).map(item=>item.id))}catch(e){toast(e.message)}}
async function refreshCaptain(){await Promise.all([loadMine(),fetchMeta(),refreshNotifications(true)]);load(false,true)}
async function refreshApplication(){application.value=await api('/applications/'+application.value.id,{manage:manage.value});loadMine();fetchMeta();load(false,true)}
async function goRecords(){tab.value='mine';myTab.value=auth.user?'cards':'outgoing'}
function navigateSection(key){if(key==='mine')goRecords();else tab.value=key}
async function ignoreBookingReminder(item){try{await api('/matches/'+item.match_id+'/reminders/ignore',{method:'POST',data:{version:item.schedule_version}});await refreshCaptain();toast('已忽略本次时段提醒，老板继续挂机')}catch(e){toast(e.message)}}
async function openNotification(item){dismissNotification();close();tab.value='mine';if(item.kind==='booking_reminder'){myTab.value='cards';await loadMine();await markNotificationsRead([item.id]);await nextTick();document.getElementById('boss-booking-'+item.application_id)?.scrollIntoView({behavior:'smooth',block:'center'});return}else if(item.kind==='partner_application'){myTab.value='partners';await nextTick();await personalPartnerBoard.value?.showIncoming(item.id)}else{myTab.value=item.side==='applicant'?'outgoing':'incoming';const credential=saved().find(r=>r.type===item.access?.type&&r.id===item.access?.id)?.manage||'';await openApplication(item.application_id||item.id,credential)}}
async function partnerRecords(){myTab.value='partners';await nextTick();if(pendingCounts.value.partners)personalPartnerBoard.value?.showIncoming()}
function recordUnread(r){return notificationItems.value.filter(item=>item.access?.type===r.type&&item.access?.id===r.id).length}
function applicationUnread(id){return unreadUpdates.value.filter(item=>item.application_id===id).length}
function openLocal(r){if(r.type==='application')openApplication(r.id,r.manage);else openDetail({id:r.id,type:r.type},r.manage)}
async function edit(){editing.value=detail.value;publishKind.value=detail.value.type;await loadMine();sheet.value='publish'}
async function status(action){try{await api('/'+detail.value.type+'-cards/'+detail.value.id+'/status',{method:'POST',data:{action},manage:manage.value});toast(action==='matched'?'已标记找到队伍':'卡片已下架');close();loadMine();load();fetchMeta()}catch(e){toast(e.message)}}
async function deleteContact(){try{const resource=sheet.value==='application'?'application':detail.value.type,id=sheet.value==='application'?application.value.id:detail.value.id;await api(`/contacts/${resource}/${id}`,{method:'DELETE',manage:manage.value});toast('你的联系方式已删除');if(sheet.value==='application')refreshApplication();else openDetail(detail.value,manage.value)}catch(e){toast(e.message)}}
function reportOpen(resource,id){report.value={resource,resource_id:id,reason:'',challenge_id:'',answer:'',website:''};sheet.value='report'}
async function submitReport(){busy.value=true;try{await api('/reports',{method:'POST',data:report.value});close();toast('已提交，管理员会复核处理')}catch(e){toast(e.message);human.value?.refresh()}finally{busy.value=false}}
function openPolicy(kind){policy.value=kind;sheet.value='policy'}
function recoveryOpen(mode,resource='boss',id=1){recoveryMode.value=mode;recoveryStage.value=0;recovery.value={resource,resource_id:id,email:'',code:''};sheet.value='recovery'}
async function recover(){busy.value=true;try{const mode=recoveryMode.value,stage=recoveryStage.value;const action=stage?(mode==='bind'?'verify':'recover'):(mode==='bind'?'bind':'send');const newToken=action==='recover'?token():manage.value;await api('/recovery/'+action,{method:'POST',data:recovery.value,manage:newToken});if(stage){if(action==='recover'){saveManaged(recovery.value.resource,recovery.value.resource_id,newToken,'找回的记录');success.value={type:recovery.value.resource,id:recovery.value.resource_id,manage:newToken};sheet.value='success'}else{toast('邮箱绑定成功');close()}}else{recoveryStage.value=1;toast('若邮箱匹配，验证码已发送')}}catch(e){toast(e.message)}finally{busy.value=false}}
function routeHash(){const match=location.hash.match(/^#manage\/(team|boss|application)\/(\d+)\/([a-zA-Z0-9_-]{40,128})$/);if(match){saveManaged(match[1],Number(match[2]),match[3],'管理链接');if(['boss','application'].includes(match[1])){tab.value='mine';myTab.value='cards';loadMine()}else openLocal({type:match[1],id:Number(match[2]),manage:match[3]})}}
onMounted(async()=>{await loadSession().catch(()=>{});await Promise.all([fetchMeta(),load()]);routeHash();window.addEventListener('hashchange',routeHash);timer=setInterval(()=>{if(!document.hidden&&!sheet.value){if(tab.value==='mine')loadMine();else load(false,true);fetchMeta()}},30000)})
onUnmounted(()=>{clearInterval(timer);clearTimeout(searchTimer);clearTimeout(noticeTimer);window.removeEventListener('hashchange',routeHash)})
</script>
<template>
<div class="app-shell"><header class="site-header"><a href="/party/" class="brand"><span class="brand-icon"><Rabbit :size="24" stroke-width="1.7"/></span><span>小白兔<span class="brand-light">组队</span></span><span class="region-label">怀旧服</span></a><div class="header-right"><a class="timer-link" href="/" target="_blank" rel="noopener">蘑菇王计时器 <ArrowUpRight :size="14"/></a><span class="header-divider"></span><button v-if="notificationsAvailable" class="icon-button header-notifications" :aria-label="pendingCount?`查看 ${pendingCount} 条消息`:'查看我的记录'" @click="goRecords"><Bell :size="19"/><span v-if="pendingCount" class="notification-count">{{badgeNumber(pendingCount)}}</span></button><button v-if="notificationsAvailable" class="icon-button notification-sound" :class="{muted:!soundEnabled}" :aria-label="soundEnabled?'关闭消息提示音':'开启消息提示音'" :title="soundEnabled?(soundReady?'消息提示音已开启':'提示音已开启，点击页面后生效'):'消息提示音已关闭'" @click="toggleSound"><Volume2 v-if="soundEnabled" :size="18"/><VolumeX v-else :size="18"/></button><button class="icon-button" :aria-label="theme==='dark'?'切换浅色主题':'切换深色主题'" @click="theme=theme==='dark'?'light':'dark'"><Sun v-if="theme==='dark'" :size="19"/><Moon v-else :size="19"/></button><button class="login-button" @click="auth.user?goRecords():sheet='auth'"><UserRound :size="16"/>{{auth.user?.username||'登录'}}</button></div></header>
<ApplicationNotice v-if="!sheet" :notice="applicationBanner" :total="pendingCount" @open="openNotification" @dismiss="dismissNotification" @ignore="ignoreBookingReminder"/><main><section class="hero" v-if="tab!=='mine'"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> 冒险岛怀旧服 · 小白兔区<span class="hero-edition">PARTY FINDER</span></div><h1>打手与老板，<br>让升级<span class="hero-accent">轻松一点。</span></h1><p>打手发布队伍，老板申请上车，找到合适的升级安排。</p><div class="hero-proof"><span><ShieldCheck :size="14"/> 免注册浏览</span><span><Users :size="14"/> 打手与老板匹配</span><span><Bookmark :size="14"/> 联系方式授权可见</span></div></div><aside class="community-panel" aria-label="组队广场概览"><div class="community-heading"><span class="community-symbol"><Rabbit :size="29" stroke-width="1.5"/></span><div><strong>打手与老板的组队广场</strong><p>发布队伍，申请上车</p></div><span class="community-live"><i class="tiny-dot"/>实时</span></div><div class="hero-stats"><div><span>挂绳队伍</span><strong>{{meta.teams.toString().padStart(2,'0')}}<small>支</small></strong></div><i></i><div><span>老板发布</span><strong>{{meta.bosses.toString().padStart(2,'0')}}<small>位</small></strong></div></div><div class="community-note"><ShieldCheck :size="14"/><span>先加微信，再确认上车</span><ArrowUpRight :size="15"/></div></aside></section>
<section class="workspace"><div class="workspace-nav"><nav class="tabs" :style="{'--nav-columns':navigation.length}" aria-label="主导航"><button v-for="section in navigation" :key="section.key" :class="{active:tab===section.key}" :aria-label="section.key==='mine'&&pendingCount?`我的记录，${pendingCount} 条消息`:section.label" :aria-pressed="tab===section.key" :aria-describedby="'nav-hint-'+section.key" @click="navigateSection(section.key)"><component :is="section.icon" :size="17"/><span class="tab-copy"><span class="tab-title">{{section.label}}<span v-if="section.key==='mine'&&pendingCount" class="notification-count" aria-hidden="true">{{badgeNumber(pendingCount)}}</span><span v-if="section.count" class="count" aria-hidden="true">{{meta[section.count]}}</span></span><small :id="'nav-hint-'+section.key">{{section.key==='mine'&&pendingCount?`${pendingCount} 条消息待查看`:section.hint}}</small></span></button></nav></div><div v-if="tab!=='mine'" class="workspace-controls" :class="{'with-search':tab==='team'||tab==='boss'}"><p class="workspace-description">{{currentSection.description}}</p><button class="button primary publish-button" @click="publish()"><Plus :size="17"/>{{currentSection.publish}}</button><div v-if="tab==='team'||tab==='boss'" class="list-toolbar"><label class="search-input"><Search :size="18"/><input v-model="query" aria-label="搜索地图或游戏 ID" placeholder="搜索地图、游戏 ID…"><kbd>/</kbd></label><div class="toolbar-right"><button class="button filter-button" :class="{filtered:activeFilters}" @click="filterOpen"><SlidersHorizontal :size="16"/> 筛选 <span v-if="activeFilters" class="filter-count">{{activeFilters}}</span></button><button class="icon-button refresh-button" aria-label="刷新列表" @click="load()"><RefreshCw :size="17" :class="{spin:loading}"/></button></div></div></div>
<PartnerBoard v-if="features.teammate_recruitment&&tab==='partner'" ref="partnerBoard" :pending-count="pendingCounts.partners" @login="sheet='auth'" @notice="toast" @refresh="fetchMeta" @report="reportOpen"/><template v-if="tab==='team'||tab==='boss'"><div class="list-caption"><span>{{activeFilters||query?'筛选结果':tab==='team'&&cardSort==='availability'?'优先可上车':'最新发布'}} <b>{{total}}</b></span><div class="card-list-order"><label v-if="tab==='team'" class="card-sort-label"><span>排序</span><select v-model="cardSort" aria-label="队伍排序"><option value="availability">优先可上车</option><option value="latest">最新发布</option></select></label><span class="hint"><i class="tiny-dot"></i> 每 30 秒自动更新</span></div></div><div v-if="loading&&!cards.length" class="cards-grid" aria-busy="true"><div v-for="n in 4" class="skeleton-card"><i></i><i></i><i></i><i></i></div></div><div v-else-if="error" class="empty-state"><ShieldCheck :size="35"/><h2>暂时没能加载出来</h2><p>{{error}}</p><button class="button" @click="load()">重新加载</button></div><template v-else-if="!cards.length"><div class="empty-state"><div class="empty-art"><div class="orbit one"></div><div class="orbit two"></div><Rabbit :size="48" stroke-width="1.1"/><span class="art-spark">+</span></div><h2>{{activeFilters||query?'还没有符合条件的卡片':tab==='team'?'发布打手队伍，等老板上车':'发布求带需求，让打手找到你'}}</h2><p>{{activeFilters||query?'试试放宽地图、等级或经验的筛选条件。':tab==='team'?'打手发布地图、经验、时段和收费，方便老板选择。':'老板填写等级、地图和在线时段，让合适的打手联系你。'}}</p><button v-if="activeFilters||query" class="button" @click="clearFilters">清除筛选</button><div v-else class="button-row"><button class="button primary" @click="publish(tab)"><Plus :size="16"/>{{tab==='team'?'发布队伍':'发布求带'}}</button><button class="button subtle" @click="tab=tab==='team'?'boss':'team'">{{tab==='team'?'查看老板发布':'查看挂绳队伍'}}<ArrowRight :size="15"/></button></div></div></template><template v-else><div class="cards-grid"><TeamCard v-for="card in cards" :key="card.type+card.id" :card="card" @detail="openDetail" @apply="apply"/></div><button v-if="hasMore" class="button load-more" :disabled="loading" @click="load(true)">{{loading?'加载中…':tab==='team'?'加载更多队伍':'加载更多求带需求'}}<ChevronDown :size="16"/></button></template><div class="how-it-works"><div><span>01</span><section><strong>{{tab==='team'?'选择合适的打手队伍':'寻找合适的老板'}}</strong><p>{{tab==='team'?'看地图、经验、空位和时段':'看等级、地图和在线时段'}}</p></section></div><ArrowRight :size="15"/><div><span>02</span><section><strong>{{tab==='boss'?'先到先得，认领后查看微信':'双方同意后交换微信'}}</strong><p>{{tab==='boss'?'系统通知老板，无需老板同意':'沟通费用、时段与安排'}}</p></section></div><ArrowRight :size="15"/><div><span>03</span><section><strong>队长确认老板上车</strong><p>打手结束挂机，老板按需评价</p></section></div></div></template>
<section v-else-if="tab==='mine'" class="my-page records-workspace">
  <div class="my-heading"><div class="avatar"><UserRound :size="24"/></div><div><h1>{{auth.user?'队伍管理':'我的上车记录'}}</h1><p>{{auth.user?'查看老板时段，集中处理上车与结束。':'查看自己的挂机时段，上车和结束由打手处理。'}}</p></div><button v-if="auth.user" class="button primary small" @click="publish('team')"><Plus :size="16"/>发布队伍</button><button v-if="auth.user" class="button small" @click="myTab=myTab==='profile'?'cards':'profile'">{{myTab==='profile'?'返回队伍':'我的资料'}}</button><template v-else><button class="button small" @click="publish('boss')"><Plus :size="15"/>发布求带</button><button class="text-button muted" @click="sheet='auth'">登录账号</button></template><button v-if="auth.user" class="icon-button" aria-label="退出登录" @click="logout"><LogOut :size="18"/></button></div>
  <div v-if="auth.user?.is_admin" class="my-actions"><button v-if="auth.user?.is_admin" class="button small" @click="sheet='admin'">管理后台</button></div>

  <p v-if="bossBookingsError" class="error" role="alert">挂机安排暂时未能加载：{{bossBookingsError}} <button class="text-button" @click="loadBossBookings">重新加载</button></p>
  <p v-if="mineError" class="error" role="alert">{{mineError}} <button class="text-button" @click="loadMine">重新加载记录</button></p>
  <section v-if="!auth.user&&waitingBossCards.length" class="waiting-boss-cards"><h2>等待打手认领 <small>{{waitingBossCards.length}} 条需求</small></h2><p class="hint">无需守着页面。被认领后，打手会获得你的微信并联系你。</p><button v-for="card in waitingBossCards" :key="card.id" class="record-row" @click="openDetail(card,card.credential)"><div><strong>{{card.map_name}} · {{card.game_id}}</strong><small>Lv.{{card.level}} · {{card.start_time}} — {{card.end_time<=card.start_time?'次日 ':''}}{{card.end_time}} · {{date(card.expires_at)}} 到期</small></div><span class="tag">待认领</span><span>查看 / 修改</span><ArrowUpRight :size="16"/></button></section>
  <BossBookings v-if="myTab!=='profile'" :bookings="bossBookings" @open="openBossBooking"/>
  <template v-if="auth.user">
    <div v-if="myTab!=='profile'" class="segmented my-segments records-tabs"><button :class="{selected:myTab==='cards'}" @click="myTab='cards'">我的队伍</button><button :class="{selected:myTab==='incoming'}" @click="myTab='incoming'">收到申请 <b v-if="pendingCounts.applications" class="notification-count">{{badgeNumber(pendingCounts.applications)}}</b></button><button :class="{selected:myTab==='outgoing'}" @click="myTab='outgoing'">申请与认领 <b v-if="unreadUpdates.some(item=>item.side==='applicant')" class="notification-count">{{badgeNumber(unreadUpdates.filter(item=>item.side==='applicant').length)}}</b></button><button v-if="features.teammate_recruitment" :class="{selected:myTab==='partners'}" @click="partnerRecords">队友记录 <b v-if="pendingCounts.partners" class="notification-count">{{badgeNumber(pendingCounts.partners)}}</b></button></div>
    <template v-if="myTab==='cards'"><CaptainDashboard ref="captainDashboard" :teams="captainTeams" @open="openApplication" @detail="openDetail" @refresh="refreshCaptain" @notice="toast" @publish="publish('team')"/><details v-if="mine.cards.some(c=>c.type==='boss')" class="captain-past"><summary>我发布的求带需求 <ChevronDown :size="15"/></summary><button class="record-row" v-for="c in mine.cards.filter(c=>c.type==='boss')" @click="openDetail(c)"><div><strong>{{c.map_name}} · {{c.game_id}}</strong><small>{{date(c.created_at)}}</small></div><span class="tag">{{labels[c.status]}}</span><ArrowUpRight :size="17"/></button></details></template>
    <PartnerBoard v-else-if="features.teammate_recruitment&&myTab==='partners'" ref="personalPartnerBoard" personal :pending-count="pendingCounts.partners" @login="sheet='auth'" @notice="toast" @refresh="fetchMeta" @report="reportOpen"/>
    <ProfilePanel v-else-if="myTab==='profile'" :has-proof="mine.has_registration_proof" @updated="loadMine"/>
    <template v-else><p v-if="!mine[myTab]?.length" class="empty-small">暂时没有申请记录。</p><button class="record-row" v-for="a in mine[myTab]" @click="openApplication(a.id)"><span class="record-icon"><Inbox :size="18"/></span><div><strong>{{a.card.map_name}} · {{a.game_id}}</strong><small>{{a.requested_start_at?date(a.requested_start_at)+' 开始 · '+a.duration_hours+' 小时':date(a.created_at)+' 提交'}}</small></div><b v-if="applicationUnread(a.id)" class="notification-count">{{badgeNumber(applicationUnread(a.id))}}</b><span class="tag">{{labels[a.match?.status||a.status]}}</span><ArrowUpRight :size="17"/></button></template>
  </template>
  <details v-if="unreadUpdates.length" class="progress-notifications records-messages"><summary><Bell :size="16"/><strong>进度消息</strong><b class="notification-count">{{badgeNumber(pendingCounts.updates)}}</b><span>{{unreadUpdates[0].label}}</span><ChevronDown :size="15"/></summary><button v-for="item in unreadUpdates" :key="item.key" class="record-row" @click="openNotification(item)"><div><strong>{{item.kind==='booking_reminder'?item.game_id+' · ':''}}{{item.label}}</strong><small>{{item.map_name}} · {{date(item.created_at)}}</small></div><span class="notification-dot" aria-label="未读消息"></span><ArrowUpRight :size="17"/></button></details>
  <details v-if="localItems.length" class="local-records" :open="!auth.user&&!bossBookings.length&&!waitingBossCards.length"><summary><Bookmark :size="16"/>{{auth.user?'本机保存的其他记录':'我的申请与求带'}} <span>{{localItems.length}}</span><ChevronDown :size="15"/></summary><button v-for="r in localItems" class="record-row" @click="openLocal(r)"><span class="record-icon"><Link2 :size="18"/></span><div><strong>{{r.type==='application'?'上车申请':r.type==='boss'?'求带需求':'队伍招募'}} #{{r.id}} · {{r.title}}</strong><small>保留原管理链接，可随时回来查看进度</small></div><b v-if="recordUnread(r)" class="notification-count">{{badgeNumber(recordUnread(r))}}</b><ArrowUpRight :size="17"/></button></details>
  <div v-else-if="!auth.user&&!bossBookings.length" class="empty-state compact"><Inbox :size="38"/><h2>还没有组队记录</h2><p>提交申请后，这里会自动保存你的管理入口。</p><button class="button" @click="tab='team'">查看挂绳队伍 <ArrowRight :size="15"/></button></div>
</section>
</section><div class="safety-strip"><ShieldCheck :size="17"/><p>安心组队，从核实信息开始。<span>平台仅提供信息撮合，不提供支付、担保或赔付。</span></p><button @click="openPolicy('safety')">防骗须知 <ArrowUpRight :size="14"/></button></div></main><footer><span>小白兔组队 <span class="footer-dot">·</span> 非游戏官方平台</span><div><button @click="openPolicy('safety')">防骗须知</button><button @click="openPolicy('privacy')">隐私政策</button><button @click="reportOpen('appeal',1)">举报与申诉</button><a href="/" target="_blank">蘑菇王计时器 ↗</a></div><span>北京时间 UTC+8</span></footer></div>
<Transition name="toast"><div v-if="notice" class="toast-message" role="status"><Check :size="16"/>{{notice}}</div></Transition>
<Sheet v-if="sheet" :key="sheet" :title="title" :wide="['publish','admin'].includes(sheet)" @close="close">
<ApplicationNotice :notice="applicationBanner" :total="pendingCount" @open="openNotification" @dismiss="dismissNotification" @ignore="ignoreBookingReminder"/>
<AuthForm v-if="sheet==='auth'" @done="onAuth"/>
<CardForm v-else-if="sheet==='publish'" :kind="publishKind" :initial="editing" :manage="manage" :maps="meta.maps" :characters="mine.characters" @saved="onSaved" @roster-updated="refreshCaptain"/>
<ApplyForm v-else-if="sheet==='apply'" :card="selected" @saved="onSaved" @publish-team="prepareClaimTeam" @browse="returnToCards" @records="close();goRecords()"/>
<ApplicationPanel @manage-time="manageBooking(application.id)" v-else-if="sheet==='application'" :row="application" :manage="manage" @refresh="refreshApplication" @notice="toast"/>
<template v-else-if="sheet==='filters'"><form class="stack" @submit.prevent="filterApply"><label>地图<select v-model="draftFilters.map_name"><option value="">全部地图</option><option v-for="m in meta.maps">{{m}}</option></select></label><div class="form-grid"><label>{{tab==='team'?'我的等级':'老板等级'}}<input type="number" v-model="draftFilters.level" min="1" max="300" placeholder="不限"></label><label v-if="tab==='team'">队伍人数<select v-model="draftFilters.capacity"><option value="">不限</option><option v-for="n in [2,3,4,5,6]" :value="n">{{n}} 人队伍</option></select></label></div><div class="form-grid"><label v-if="features.teammate_recruitment&&tab==='team'">花类型<select v-model="draftFilters.flower"><option value="">不限</option><option value="active">活花</option><option value="afk">死花</option><option value="none">无花</option><option v-if="tab==='boss'" value="any">任意花</option></select></label><label :class="{'full-row':!features.teammate_recruitment}">收费模式<select v-model="draftFilters.price_mode"><option value="">不限</option><option value="hour">按小时</option><option value="experience">包经验</option><option v-if="tab==='boss'" value="any">自由协商</option></select></label></div><div class="form-grid"><label>经验最低（点/小时）<input type="number" v-model="draftFilters.exp_min" min="0" placeholder="不限"></label><label>经验最高（点/小时）<input type="number" v-model="draftFilters.exp_max" min="0" placeholder="不限"></label></div><label>可服务时间（北京时间）<input type="time" v-model="draftFilters.at_time"></label><label v-if="tab==='team'" class="check-label"><input type="checkbox" v-model="draftFilters.available">只看有空位的队伍</label><div class="button-row"><button type="button" class="button" @click="clearFilters();close()">重置</button><button class="button primary grow">查看结果 <ArrowRight :size="16"/></button></div></form></template>
<template v-else-if="sheet==='detail'&&detail"><div class="stack"><div class="detail-tags"><span v-if="features.teammate_recruitment&&detail.type==='team'" class="tag flower" :class="detail.flower"><Flower2 :size="13"/>{{flowers[detail.flower]}}</span><span v-if="detail.type==='team'" class="tag">招 {{detail.boss_slots??(detail.capacity-detail.fighter_count-detail.priest_count)}} 位老板</span><span class="tag">{{labels[detail.status]}}</span></div><div class="detail-hero"><div><small>{{detail.type==='boss'?'期望经验 / 小时':'预估经验 / 小时'}}</small><strong>{{number(detail.exp_min)}}–{{number(detail.exp_max)}}<span> 万</span></strong></div><div><small>{{detail.type==='team'?'收费标准':'收费偏好'}}</small><strong :class="{'experience-price':detail.price_mode==='experience'}">{{priceValue(detail)}}<span v-if="detail.price_mode!=='any'">{{priceUnit(detail)}}</span></strong></div></div><dl class="detail-list"><div><dt>角色</dt><dd>{{detail.game_id}} · Lv.{{detail.level}}</dd></div><div v-if="detail.type==='team'"><dt>等级范围</dt><dd>Lv.{{detail.level_min}}–{{detail.level_max}} · 余 {{detail.remaining}} 位</dd></div><div><dt>{{detail.type==='boss'?'发布时的期望时段':'挂机时段'}}</dt><dd>{{detail.start_time}} – {{detail.end_time<=detail.start_time?'次日 ':''}}{{detail.end_time}} <small>北京时间</small></dd></div><div v-if="detail.night_price"><dt>包夜价</dt><dd>{{priceValue(detail,'night_price')}} {{priceUnit(detail,'night_price')}}</dd></div><div><dt>卡片到期</dt><dd>{{date(detail.expires_at)}}</dd></div></dl><p v-if="detail.notes" class="note">{{detail.notes}}</p><div v-if="detail.publisher" class="publisher-box"><span class="avatar">{{detail.publisher.name.slice(0,1)}}</span><div><strong>{{detail.publisher.name}}</strong><p>{{new Date(detail.publisher.registered_at).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})}} 加入 · {{detail.completed_count}} 次挂机已完成</p></div></div><div v-if="detail.reviews?.length" class="reviews"><h4>经审核的组队评价</h4><article v-for="r in detail.reviews"><div class="detail-tags"><span class="tag" v-for="t in r.tags">{{t}}</span></div><p>{{r.body}}</p></article></div><div v-if="detail.public_contact" class="contact-card"><small>发布者主动公开的联系方式</small><strong>{{detail.public_contact.wechat}}</strong><img v-if="detail.public_contact.qr" :src="detail.public_contact.qr" class="qr-preview" alt="公开联系二维码"></div><div class="risk-note"><ShieldCheck :size="18"/><p>先核对游戏角色，再确认费用与时段。平台仅提供信息撮合，不收款、不担保，不承诺经验收益。勿提供账号密码、验证码，谨慎预付。</p></div><template v-if="detail.is_owner"><div class="button-row"><button v-if="['active','full'].includes(detail.status)" class="button primary" @click="edit">编辑卡片</button><button v-if="detail.status==='active'&&detail.type==='boss'" class="button" @click="status('matched')">已找到队伍</button><button v-if="['active','full'].includes(detail.status)" class="button" @click="status('close')">下架</button></div><div class="button-row"><button class="text-button" @click="deleteContact">删除联系方式</button><button v-if="manage&&detail.type==='boss'" class="text-button" @click="recoveryOpen('bind','boss',detail.id)">绑定恢复邮箱</button></div><h4>{{detail.type==='boss'?'认领记录':'收到的申请'}}</h4><p v-if="!detail.applications?.length" class="hint">暂无申请。</p><button v-for="a in detail.applications" class="record-row" @click="openApplication(a.id,manage)"><div><strong>{{a.game_id}} · Lv.{{a.level}}</strong><small>{{date(a.created_at)}}</small></div><b v-if="applicationUnread(a.id)" class="notification-count">{{badgeNumber(applicationUnread(a.id))}}</b><span class="tag">{{labels[a.match?.status||a.status]}}</span><ArrowUpRight :size="17"/></button></template><button v-else class="button primary full" :disabled="detail.status!=='active'" @click="apply(detail)">{{detail.status==='active'?(detail.type==='team'?'申请上车':'认领老板'):labels[detail.status]}}<ArrowRight :size="17"/></button><button class="text-button muted" @click="reportOpen(detail.type,detail.id)"><Flag :size="13"/> 举报此卡片</button></div></template>
<template v-else-if="sheet==='success'"><div class="success-mark"><Check :size="30"/></div><h3 class="center">{{success.type==='application'?'申请已送达':'卡片已保存'}}</h3><p class="muted center">{{success.type==='application'?'等待发布者处理，同意后即可查看联系方式。':success.type==='team'?'队伍已发布，老板可以查看并申请上车。':'求带需求已发布。被认领后会收到通知，上车与结束均由打手处理，无需你反复确认。'}}</p><div v-if="success.manage" class="stack saved-link"><strong><Link2 :size="17"/> 已保存到本机“我的记录”</strong><p>这是管理此记录的凭证，请勿分享给其他人。链接只保存在本机，清除浏览器数据会丢失；未绑定验证邮箱时无法恢复。</p><input readonly :value="manageLink(success.type,success.id,success.manage)" aria-label="专属管理链接"><button class="button full" @click="copy(manageLink(success.type,success.id,success.manage))"><Copy :size="16"/> 备份管理链接</button></div><button class="button primary full" @click="close();tab='mine';myTab='cards';loadMine()">查看我的记录 <ArrowRight :size="16"/></button></template>
<template v-else-if="sheet==='policy'"><div class="prose" v-if="policy==='safety'"><p class="lead">组队前，多核对一步。</p><h3>先确认身份和安排</h3><p>在游戏中核对角色 ID、等级、队伍成员和地图。事先说清时段、计费方式、断线、补药和中途退出如何处理。预估经验是发布者提供的信息，不代表收益保证。</p><h3>保护你的账号与资金</h3><p>不要向任何人提供游戏账号密码、短信验证码或支付验证码。对超低价、催促转账和“平台担保”保持警惕，谨慎预付大额费用。本站没有客服代收款，也没有支付、托管或担保服务。</p><h3>有争议时留存证据</h3><p>保留游戏记录和交易沟通记录。可举报卡片、申请复核或在撮合记录标记争议；平台可隐藏违规内容和封禁账号，但不承诺追回款项或提供赔付。</p><h3>平台边界</h3><p>本平台为玩家信息交流工具，与游戏官方没有隶属、合作或担保关系。请自行确认相关行为符合适用的游戏条款和法律要求。</p><button class="button" @click="reportOpen('appeal',1)">提交举报或申诉 <ArrowRight :size="16"/></button></div><div class="prose" v-else><p class="lead">只收集完成组队所需的信息。</p><h3>公开信息</h3><p>发布卡片中的角色 ID、等级、地图、经验、价格、时段和备注对访客公开。用户名、注册日期、打手确认结束数和审核后的评价用于帮助判断发布者情况。请不要在备注中填写敏感信息。</p><h3>联系方式与授权</h3><p>微信号和二维码加密保存。队伍上车申请被接受后向双方开放；老板发布的求带需求由首位成功认领的打手直接获得微信，系统通知老板，无需再次同意。老板微信不公开展示，队伍发布者可以主动公开自己的联系方式。账号微信资料用于自动填写，随账号保留，每 7 天最多修改一次，可通过隐私请求申请删除。记录中的联系方式可单独删除，卡片到期七天后自动清理；删除某条记录的联系方式不会删除账号微信资料。</p><h3>截图与邮箱</h3><p>打手注册必须提交包含完整「角色能力」窗口的个人截图，仅个人情报资料卡无法通过。截图经自动格式与文字识别校验后，去除图片元数据并加密保存，与账号、角色名、职业、等级和提交时间关联，仅本人及管理员可查看，不对外公开。注册失败的图片不留存。注册截图随账号保留并纳入备份，可通过申诉申请删除；截图校验不代表角色归属认证。发布和申请表单中的可选截图识别仍为临时处理，完成或失败后删除原图。恢复邮箱仅在邮件服务已配置时可绑定，需完成验证码验证。</p><h3>管理凭证与会话</h3><p>匿名管理链接由浏览器产生随机凭证，服务端只保存哈希。凭证保存在本机浏览器和你自行备份的链接中。登录使用必要的会话 Cookie，不使用广告追踪。请不要公开管理链接。</p><h3>删除与申诉</h3><p>你可以自行下架卡片并删除联系方式。账号删除、其他个人信息删除或审核异议，请通过举报与申诉入口提交账号或记录编号，管理员将核对身份后处理。操作审计保留用于维护平台安全。</p><p class="hint">更新于 2026 年 10 月 26 日</p></div></template>
<form v-else-if="sheet==='report'" class="stack" @submit.prevent="submitReport"><p class="muted">请描述可核实的事实。不要在此提交账号密码、验证码或完整付款信息。</p><div class="form-grid"><label>对象<select v-model="report.resource"><option value="team">队伍招募</option><option value="boss">求带需求</option><option v-if="features.teammate_recruitment" value="partner">队友招募 / 祭司求职</option><option value="review">评价</option><option value="user">账号</option><option value="appeal">申诉 / 隐私请求</option></select></label><label>记录或账号编号<input type="number" min="1" v-model.number="report.resource_id" required></label></div><label>说明<textarea v-model="report.reason" minlength="5" maxlength="600" rows="5" required placeholder="说明对象、发生时间和需要复核的情况"></textarea></label><HumanCheck ref="human" v-model="report"/><button class="button primary full" :disabled="busy">提交复核</button></form>
<AdminPanel v-else-if="sheet==='admin'"/>
<template v-else-if="sheet==='recovery'"><div v-if="!meta.email_recovery" class="prose"><Mail :size="30"/><h3>邮箱恢复暂未开通</h3><p>请先妥善保存专属管理链接。当前尚未接入发信邮箱，因此不能承诺通过邮箱找回。若已丢失链接且没有已验证的恢复渠道，将无法恢复匿名记录。</p></div><form v-else class="stack" @submit.prevent="recover"><div v-if="recoveryMode==='recover'" class="form-grid"><label>记录类型<select v-model="recovery.resource"><option value="boss">求带需求</option><option value="application">申请</option></select></label><label>编号<input type="number" min="1" v-model.number="recovery.resource_id" required></label></div><label>绑定邮箱<input type="email" v-model="recovery.email" required></label><label v-if="recoveryStage">验证码<input v-model="recovery.code" inputmode="numeric" maxlength="6" required></label><button class="button primary full" :disabled="busy">{{recoveryStage?'验证并继续':'发送验证码'}}</button></form></template>
<div v-if="sheet==='application'" class="panel-footer-actions"><button v-if="application.side==='applicant'" class="text-button" @click="deleteContact">删除我的联系方式</button><button v-if="manage&&application.side==='applicant'" class="text-button" @click="recoveryOpen('bind','application',application.id)">绑定恢复邮箱</button><button class="text-button" @click="reportOpen('appeal',application.id)">举报 / 申诉</button></div>
</Sheet>
</template>
